  await page.locator('.card').nth(15).click();
  await expect(page.locator('.stats dd').nth(3)).toHaveText('8');
  expect(await exportedSnapshot(page)).toMatchObject({ version: 2, name: 'Finished', moves: 8 });
  await page.reload();
  await expect(page.locator('.stats dd').nth(3)).toHaveText('8');
});
